$('#drawerClose').addEventListener('click',closeDrawer);$('#drawer').addEventListener('click',e=>{if(e.target===e.currentTarget)closeDrawer()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()})
function csv(rows,name){if(!rows.length){status('Nada para exportar.');return}const head=Object.keys(rows[0]);const body=[head.join(';')].concat(rows.map(r=>head.map(h=>{const v=r[h]==null?'':String(r[h]).replace(/"/g,'""');return /[;"\n]/.test(v)?`"${v}"`:v}).join(';'))).join('\n');const blob=new Blob(['\ufeff'+body],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href)}
$('#exportQuotes').addEventListener('click',()=>csv((state.quotes||[]).filter(q=>q.status!=='inactive').map(q=>({grao:q.commodity,preco:q.price,unidade:q.priceUnit,praca:q.region,fonte:q.sourceName,prazo:q.paymentTerms,observada_em:q.observedAt,confianca:q.confidence,link:q.sourceUrl})),'cotacoes.csv'))
