function ownLatest(){const own=state.ownSource;if(!own)return {};const out={};for(const c of own.commodities||[]){const q=(state.quotes||[]).filter(x=>x.status!=='inactive'&&x.commodity===c&&x.sourceId===own.id).sort((l,r)=>String(r.observedAt).localeCompare(String(l.observedAt)))[0];if(q)out[c]=q}return out}
function portLatest(){const out={};for(const ps of state.portSources||[]){out[ps.id]={};for(const c of ps.commodities||[]){const q=(state.quotes||[]).filter(x=>x.status!=='inactive'&&x.commodity===c&&x.sourceId===ps.id).sort((l,r)=>String(r.observedAt).localeCompare(String(l.observedAt)))[0];if(q)out[ps.id][c]=q}}return out}
function comparisonTable(compact){
 const cmp=state.comparison;const own=ownLatest();const grains=['soja','milho','trigo','canola'];const label=v=>(state.catalog.commodities.find(c=>c.value===v)||{}).label||v;const ports=portLatest()
 const portIds=new Set((state.portSources||[]).map(p=>p.id));const rows=(cmp?.results||[]).filter(r=>!portIds.has(r.sourceId)&&(!compact||r.status==='ok'))
 const portRows=(state.portSources||[]).map(ps=>{const q=ports[ps.id]||{};const has=Object.keys(q).length;if(compact&&!has)return '';const auto=(cmp?.results||[]).find(r=>r.sourceId===ps.id);return `<tr class="portrow"><td><b>${esc(ps.name)}</b><small>porto • base = C.Vale − porto${auto?` • automático ${auto.status==='ok'?'✓':'(sem leitura)'}`:' • manual'}</small></td>${grains.map(g=>{const pq=q[g];if(!pq)return '<td class="none">—</td>';const o=own[g];const base=o?o.price-pq.price:null;return `<td><b>${money(pq.price)}</b><small>${dt(pq.observedAt)}${pq.paymentTerms?' • '+esc(pq.paymentTerms):''}</small>${base!=null?`<em class="${base<-30?'up':''}">base ${base>=0?'+':''}${money(base)}</em>`:''}</td>`}).join('')}<td>${auto?'auto':'manual'}</td></tr>`}).join('')
 if(!cmp)return `<table class="cmptable"><thead><tr><th>Comprador</th>${grains.map(g=>`<th>${esc(label(g))}</th>`).join('')}<th>Leitura</th></tr></thead><tbody>${portRows}</tbody></table><div class="empty"><p>Ainda sem leitura automática dos concorrentes. Clique em “Buscar agora” ou aguarde a atualização periódica.</p></div>`
 const cell=(r,c)=>{const p=r.prices?.[c];if(!p)return '<td class="none">—</td>';const o=own[c];const price=p.priceUnit==='BRL/t'?p.price*0.06:p.price;const diff=o?price-o.price:null;return `<td><b>${money(price)}</b>${p.priceUnit==='BRL/t'?`<small>${money(p.price)}/t</small>`:''}${diff!=null?`<em class="${diff>0.005?'up':diff<-0.005?'down':''}">${diff>=0?'+':''}${money(diff)}</em>`:''}${compact?'':`<button class="mini" type="button" data-save="${r.sourceId}" data-c="${c}" title="${esc(p.snippet||'')}">salvar</button>`}</td>`}
 return `<table class="cmptable"><thead><tr><th>Comprador</th>${grains.map(g=>`<th>${esc(label(g))}</th>`).join('')}<th>Leitura</th></tr></thead><tbody>
  <tr class="ownrow"><td><b>C.Vale — São Luiz Gonzaga</b><small>nossa cotação</small></td>${grains.map(g=>own[g]?`<td><b>${money(own[g].price)}</b><small>${dt(own[g].observedAt)}${own[g].paymentTerms?' • '+esc(own[g].paymentTerms):''}</small></td>`:'<td class="none">preencher</td>').join('')}<td>manual</td></tr>
  ${portRows}
  ${rows.map(r=>`<tr class="${r.status}"><td><b>${esc(r.name)}</b><small>${esc(r.region||'')}</small></td>${grains.map(g=>cell(r,g)).join('')}<td>${r.status==='ok'?`<span class="tag fresh">lida</span><small>${r.pageDate?'data na página '+dt(r.pageDate):''}${r.history?.length?` • ${r.history.length} datas de histórico`:''}</small>`:r.status==='empty'?`<span class="tag attention">sem preço</span>`:`<span class="tag expired">falhou</span><small>${esc(r.error||'')}</small>`}${r.url?`<a class="mini" href="${esc(r.url)}" target="_blank" rel="noreferrer">abrir</a>`:''}</td></tr>`).join('')}
 </tbody></table>${compact?'':`<p class="muted">Diferença mostrada contra o preço C.Vale do mesmo grão. Leituras automáticas entram com confiança reduzida e ficam marcadas como “auto”.</p>`}`
}
