const MONTHS=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez']
const PALETTE=['#1E9E6A','#B3457A','#7A5AF8','#C1521B','#2A9DB5','#8C7A00','#3C6E9B','#A83B3B']
const chartState={sel:{},data:{}}
function seriesFor(c){
 const base=[{key:'own',label:'C.Vale',points:c.series.own,color:'#0758B6',stats:c.seriesStats?.own||null},{key:'comp',label:'Média concorrentes',points:c.series.competitors,color:'#D28A00',stats:c.seriesStats?.competitors||null},{key:'port',label:'Porto (média)',points:c.series.port,color:'#5B6B7C',stats:c.seriesStats?.port||null}]
 const extra=(c.sources||[]).filter(s=>s.kind!=='own').map((s,i)=>({key:'src:'+s.key,label:s.label+(s.kind==='port'&&!/porto/i.test(s.label)?' (porto)':''),points:s.points,color:PALETTE[i%PALETTE.length],stats:{avg:s.avg,min:s.min,max:s.max,days:s.days,last:s.last,lastDate:s.lastDate},source:true,kind:s.kind,region:s.region}))
 return base.concat(extra)
}
function chartSelection(c){const all=seriesFor(c);if(!chartState.sel[c.commodity])chartState.sel[c.commodity]=['own','comp','port'];const sel=chartState.sel[c.commodity];return all.map(s=>({...s,on:sel.includes(s.key)}))}
function lineChart(seriesList,{w=640,h=240,id=''}={}){
 const vis=seriesList.filter(s=>s.on&&s.points.length)
 const all=vis.flatMap(s=>s.points);if(all.length<2)return {svg:'<p class="meta">Registre ou importe cotações (ou marque mais séries) para desenhar a linha do ano.</p>',geom:null}
 const T0=d=>new Date(d+'T12:00:00Z').getTime()
 const xs=all.map(p=>T0(p.d));const ys=all.map(p=>p.p)
 const x0=Math.min(...xs),x1=Math.max(...xs);let y0=Math.min(...ys),y1=Math.max(...ys);if(y1===y0){y0-=1;y1+=1}const padY=(y1-y0)*.12;y0-=padY;y1+=padY
 const L=44,R=150,T=12,B=26
 const X=t=>L+(x1===x0?0:(t-x0)/(x1-x0))*(w-L-R);const Y=v=>T+(1-(v-y0)/(y1-y0))*(h-T-B)
 const ticks=4;const grid=[...Array(ticks+1)].map((_,i)=>{const v=y0+(y1-y0)*i/ticks;return `<line x1="${L}" x2="${w-R}" y1="${Y(v).toFixed(1)}" y2="${Y(v).toFixed(1)}" class="grid"/><text x="${L-6}" y="${(Y(v)+4).toFixed(1)}" class="ax" text-anchor="end">${Math.round(v)}</text>`}).join('')
 const months=[];let cursor=new Date(x0);cursor.setUTCDate(1);while(cursor.getTime()<=x1){const t=cursor.getTime();if(t>=x0)months.push(`<text x="${X(t).toFixed(1)}" y="${h-8}" class="ax" text-anchor="middle">${MONTHS[cursor.getUTCMonth()]}</text>`);cursor.setUTCMonth(cursor.getUTCMonth()+1)}
 const used=[];const labelY=y=>{let yy=y;for(let k=0;k<12;k++){if(used.every(u=>Math.abs(u-yy)>=11))break;yy+=11}used.push(yy);return yy}
 const paths=vis.map((s,si)=>{const d=s.points.map((p,i)=>`${i?'L':'M'}${X(T0(p.d)).toFixed(1)},${Y(p.p).toFixed(1)}`).join(' ');const last=s.points[s.points.length-1];const avgLine=s.stats?.avg!=null&&s.stats.days>=3?`<line x1="${L}" x2="${w-R}" y1="${Y(s.stats.avg).toFixed(1)}" y2="${Y(s.stats.avg).toFixed(1)}" class="avg" style="stroke:${s.color}"/>`:'';return `<g class="ser" data-k="${esc(s.key)}">${avgLine}<path d="${d}" pathLength="1" class="line" style="stroke:${s.color};animation-delay:${si*90}ms"/>${s.points.length===1?`<circle cx="${X(T0(last.d)).toFixed(1)}" cy="${Y(last.p).toFixed(1)}" r="3.5" style="fill:${s.color}"/>`:''}<text x="${(X(T0(last.d))+6).toFixed(1)}" y="${(labelY(Y(last.p))+4).toFixed(1)}" class="lbl" style="fill:${s.color}">${esc(s.label.length>18?s.label.slice(0,17)+'…':s.label)} ${money(last.p)}</text><circle class="mk" data-k="${esc(s.key)}" r="0" cx="${L}" cy="${T}" style="fill:${s.color}"/></g>`}).join('')
 const svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-labelledby="${id}t"><title id="${id}t">Linha do ano</title>${grid}${months}${paths}<line class="xh" x1="${L}" x2="${L}" y1="${T}" y2="${h-B}" opacity="0"/><rect class="ov" x="${L}" y="${T}" width="${w-L-R}" height="${h-T-B}" fill="transparent"/></svg>`
 const dates=[...new Set(all.map(p=>p.d))].sort()
 return {svg,geom:{w,h,L,R,T,B,x0,x1,y0,y1,dates,vis}}
}
function mountChart(wrap,geom){
 const svg=wrap.querySelector('svg.chart');if(!svg||!geom)return
 const tip=wrap.querySelector('.tip');const T0=d=>new Date(d+'T12:00:00Z').getTime()
 const X=t=>geom.L+(geom.x1===geom.x0?0:(t-geom.x0)/(geom.x1-geom.x0))*(geom.w-geom.L-geom.R);const Y=v=>geom.T+(1-(v-geom.y0)/(geom.y1-geom.y0))*(geom.h-geom.T-geom.B)
 const xh=svg.querySelector('.xh');const marks=[...svg.querySelectorAll('.mk')]
 const show=(clientX,clientY)=>{
  const r=svg.getBoundingClientRect();const x=(clientX-r.left)/r.width*geom.w;const t=geom.x0+Math.min(1,Math.max(0,(x-geom.L)/(geom.w-geom.L-geom.R)))*(geom.x1-geom.x0)
  let best=geom.dates[0];let bd=Infinity;for(const d of geom.dates){const dd=Math.abs(T0(d)-t);if(dd<bd){bd=dd;best=d}}
  const px=X(T0(best));xh.setAttribute('x1',px.toFixed(1));xh.setAttribute('x2',px.toFixed(1));xh.setAttribute('opacity','1')
  const rows=[];const exact=[]
  for(const s of geom.vis){const m=marks.find(k=>k.dataset.k===s.key);let p=s.points.find(q=>q.d===best);let approx=false;if(!p){const near=s.points.map(q=>({q,dd:Math.abs(T0(q.d)-T0(best))})).sort((a,b)=>a.dd-b.dd)[0];if(near&&near.dd<=15*864e5){p=near.q;approx=true}}
   if(p){m.setAttribute('cx',X(T0(p.d)).toFixed(1));m.setAttribute('cy',Y(p.p).toFixed(1));m.setAttribute('r',approx?'3':'5.5');m.style.opacity=approx?'.55':'1';if(!approx)exact.push(p.p);rows.push(`<div class="trow"><i style="background:${s.color}"></i><span>${esc(s.label)}${approx?' <em>≈ '+dt(p.d)+'</em>':''}</span><b>${money(p.p)}</b><small>${s.stats?.avg!=null?'média 12m '+money(s.stats.avg):''}</small></div>`)}
   else{m.setAttribute('r','0');rows.push(`<div class="trow off"><i style="background:${s.color}"></i><span>${esc(s.label)}</span><b>—</b><small></small></div>`)}}
  const avgDay=exact.length?exact.reduce((a,b)=>a+b,0)/exact.length:null
  tip.innerHTML=`<header>${dt(best)}</header>${rows.join('')}${avgDay!=null?`<footer>Média exata do dia (${exact.length} série${exact.length>1?'s':''}): <b>${money(avgDay)}</b></footer>`:''}`
  tip.hidden=false;const wr=wrap.getBoundingClientRect();const tw=tip.offsetWidth;let left=clientX-wr.left+14;if(left+tw>wr.width-8)left=clientX-wr.left-tw-14;if(left<8)left=8;tip.style.left=left+'px';tip.style.top=Math.max(4,Math.min(clientY-wr.top-10,wr.height-tip.offsetHeight-4))+'px'
 }
 const hide=()=>{xh.setAttribute('opacity','0');marks.forEach(m=>m.setAttribute('r','0'));tip.hidden=true}
 svg.addEventListener('pointermove',e=>show(e.clientX,e.clientY));svg.addEventListener('pointerdown',e=>show(e.clientX,e.clientY));svg.addEventListener('pointerleave',hide)
}
function renderPriceChart(i){
 const c=(state.priceYear||[])[i];const wrap=$('#chart-'+i);if(!c||!wrap)return
 const series=chartSelection(c);const {svg,geom}=lineChart(series,{id:'c'+i})
 const on=series.filter(s=>s.on)
 const tableRows=[...new Set(on.flatMap(s=>s.points.map(p=>p.d)))].sort().slice(-60).reverse().map(d=>`<tr><td>${dt(d)}</td>${on.map(s=>{const p=s.points.find(x=>x.d===d);return `<td>${p?money(p.p):'—'}</td>`}).join('')}</tr>`).join('')
 wrap.innerHTML=`<div class="chips" role="group" aria-label="Séries do gráfico">${series.map(s=>`<label class="chip ${s.on?'on':''}" style="--c:${s.color}" title="${esc(s.region||'')}${s.stats?' • média 12m '+money(s.stats.avg)+' • '+s.stats.days+' dia(s)':''}"><input type="checkbox" data-k="${esc(s.key)}" ${s.on?'checked':''}><i></i>${esc(s.label)}${s.stats?`<small>${money(s.stats.avg)}</small>`:'<small>sem dados</small>'}</label>`).join('')}<span class="chipsep"></span><button class="mini" type="button" data-all="1">todas</button><button class="mini" type="button" data-all="0">padrão</button><button class="mini" type="button" data-table="${i}">tabela</button></div><div class="chartarea">${svg}<div class="tip" hidden></div></div><div class="tablewrap" id="table-${i}" hidden><table class="cmptable"><thead><tr><th>Data</th>${on.map(s=>`<th>${esc(s.label)}</th>`).join('')}</tr></thead><tbody>${tableRows||'<tr><td colspan="9">Sem dados</td></tr>'}</tbody></table></div><p class="meta chartnote">Passe o mouse (ou toque) sobre a linha para ver o preço exato de cada série no dia, a média das 12 últimas meses de cada uma (linha pontilhada) e a média exata do dia. Marque ou desmarque concorrentes para comparar.</p>`
 mountChart(wrap.querySelector('.chartarea'),geom)
 wrap.querySelectorAll('.chip input').forEach(cb=>cb.addEventListener('change',()=>{const sel=new Set(chartState.sel[c.commodity]);cb.checked?sel.add(cb.dataset.k):sel.delete(cb.dataset.k);chartState.sel[c.commodity]=[...sel];renderPriceChart(i)}))
 wrap.querySelectorAll('.chip').forEach(ch=>{const k=ch.querySelector('input').dataset.k;ch.addEventListener('pointerenter',()=>{wrap.querySelectorAll('svg.chart .ser').forEach(g=>g.classList.toggle('dim',g.dataset.k!==k))});ch.addEventListener('pointerleave',()=>wrap.querySelectorAll('svg.chart .ser').forEach(g=>g.classList.remove('dim')))})
 wrap.querySelectorAll('[data-all]').forEach(b=>b.addEventListener('click',()=>{chartState.sel[c.commodity]=b.dataset.all==='1'?series.filter(s=>s.points.length).map(s=>s.key):['own','comp','port'];renderPriceChart(i)}))
 wrap.querySelector('[data-table]').addEventListener('click',e=>{const t=$('#table-'+i);t.hidden=!t.hidden;e.target.textContent=t.hidden?'tabela':'ocultar tabela'})
}
function seasonBars(seasonal,{w=640,h=120}={}){
 if(!seasonal)return ''
 const idx=seasonal.index;const y0=Math.min(...idx)-3,y1=Math.max(...idx)+3;const L=34,R=8,T=10,B=24;const bw=(w-L-R)/12
 const Y=v=>T+(1-(v-y0)/(y1-y0))*(h-T-B)
 return `<svg class="chart bars" viewBox="0 0 ${w} ${h}" role="img"><title>Índice sazonal indicativo</title><line x1="${L}" x2="${w-R}" y1="${Y(100).toFixed(1)}" y2="${Y(100).toFixed(1)}" class="grid"/><text x="${L-4}" y="${(Y(100)+4).toFixed(1)}" class="ax" text-anchor="end">100</text>${idx.map((v,i)=>{const x=L+i*bw+2;const y=Y(v);const base=Y(y0);return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${(bw-4).toFixed(1)}" height="${(base-y).toFixed(1)}" rx="3" class="bar${i+1===seasonal.currentMonth?' now':''}" style="animation-delay:${i*40}ms"><title>${MONTHS[i]}: índice ${v}</title></rect><text x="${(x+(bw-4)/2).toFixed(1)}" y="${h-8}" class="ax" text-anchor="middle">${MONTHS[i]}</text>${i+1===seasonal.currentMonth||v===Math.max(...idx)||v===Math.min(...idx)?`<text x="${(x+(bw-4)/2).toFixed(1)}" y="${(y-4).toFixed(1)}" class="ax bold" text-anchor="middle">${v}</text>`:''}`}).join('')}</svg>`
}
